-- Field Shift: the 64 districts, generated from data/districts.ts.
on conflict (id) do update set
  name = excluded.name, name_bn = excluded.name_bn, division = excluded.division,
  lat = excluded.lat, lng = excluded.lng, soil = excluded.soil, rainfall = excluded.rainfall,
  temp = excluded.temp, risk = excluded.risk, risk_bn = excluded.risk_bn;
